  }

  // ── Run + parse ────────────────────────────────────────────────

  private async runOne(
    provider: LLMProvider,
    prompt: string,
    variant: number = 0,
    extraTemperatureBump: number = 0,
    modelOverride?: string,
  ): Promise<{
    text: string
    usage: ProviderUsage
    redactions: RedactionCount[]
  }> {
    const temperature = Math.min(
      1.0,
      0.6 + variant * 0.07 + extraTemperatureBump,
    )
    const { sanitized, redactions } = sanitizeOutboundPrompt(prompt)
    // AI-2.2: honour the operator's per-feature model for all listing
    // content, while still respecting an explicit per-call override.
    const model =
      modelOverride ?? (await resolveModelForFeature('listing-content', provider))
    const result = await provider.generate({
      prompt: sanitized,
      temperature,
      jsonMode: true,
      model,
    })
    return { ...result, redactions }
  }

  private parseJson<T>(raw: string, field: string): T {
    const cleaned = raw
      .replace(/^```(?:json)?\s*/i, '')
      .replace(/```\s*$/i, '')
      .trim()
    try {
      return JSON.parse(cleaned) as T
    } catch (e: any) {
      throw new Error(
        `Gemini returned invalid JSON for ${field}: ${e?.message ?? String(e)}`,
      )
    }
  }

  private parseTitle(raw: string): TitleResult {
    const j = this.parseJson<{ content?: string; insights?: string[] }>(
      raw,
      'title',
    )
    const content = (j.content ?? '').trim()
    return {
      content,
      charCount: content.length,
      insights: Array.isArray(j.insights) ? j.insights.slice(0, 6) : [],
    }
  }

  private parseBullets(raw: string): BulletsResult {
    const j = this.parseJson<{ content?: string[]; insights?: string[] }>(
      raw,
      'bullets',
    )
    const content = Array.isArray(j.content)
      ? j.content.slice(0, 5).map((s) => String(s).trim())
      : []
    return {
      content,
      charCounts: content.map((s) => s.length),
      insights: Array.isArray(j.insights) ? j.insights.slice(0, 6) : [],
    }
  }

  private parseDescription(raw: string): DescriptionResult {
    const j = this.parseJson<{
      content?: string
      preview?: string
      insights?: string[]
    }>(raw, 'description')
    const content = (j.content ?? '').trim()
    const preview =
      j.preview ?? content.replace(/<[^>]+>/g, '').slice(0, 240).trim()
    return {
      content,
      preview,
      insights: Array.isArray(j.insights) ? j.insights.slice(0, 6) : [],
    }
  }

  private parseKeywords(raw: string): KeywordsResult {
    const j = this.parseJson<{ content?: string; insights?: string[] }>(
      raw,
      'keywords',
    )
    const content = (j.content ?? '').trim()
    return {
      content,
      charCount: content.length,
      insights: Array.isArray(j.insights) ? j.insights.slice(0, 6) : [],
    }
  }
}

function truncate(s: string, max: number): string {
  if (s.length <= max) return s
  return s.slice(0, max - 1) + '…'
}

// AI-4.7 — clamp a candidate score to the 0–100 range. Returns 0 for
// non-numeric / NaN / Infinity. Used by parseQualityScores to keep
// AI hallucinations (e.g. score=999) from poisoning the rollup.
function clampScore(raw: unknown): number {
  if (typeof raw !== 'number' || !Number.isFinite(raw)) return 0
  if (raw < 0) return 0
  if (raw > 100) return 100
  return Math.round(raw)
}

function flattenAttrs(obj: Record<string, unknown>): string {
  const parts: string[] = []
  for (const [k, v] of Object.entries(obj)) {
    if (v == null) continue
    if (typeof v === 'object') {
      const inner = flattenAttrs(v as Record<string, unknown>)
      if (inner) parts.push(`${k}{${inner}}`)
    } else {
      parts.push(`${k}=${String(v)}`)
    }
  }
  return parts.join(', ')
}

import { assertLegacyPresentationPublishAllowed } from '../ebay-presentation-consumer.service.js'
/**
 * DD.4 — eBay publish adapter (Inventory API).
 *
 * Three-step flow per eBay's modern selling stack:
 *   1. PUT  /sell/inventory/v1/inventory_item/{sku}
 *   2. POST /sell/inventory/v1/offer
 *   3. POST /sell/inventory/v1/offer/{offerId}/publish
 *
 * NOT END-TO-END TESTED — wiring is real but exercising it requires
 * eBay developer credentials + a sandbox/production seller account
 * with policies (payment, return, fulfillment) attached. See
 * TECH_DEBT #35 for the gating items.
 *
 * The adapter never throws; it returns either a success result with
 * the offerId and listingId or a failure result with the eBay error
 * message. The caller (channel-publish.service.ts) maps that into a
 * SubmissionEntry.
 */

import prisma from '../../db.js'
import { ebayAuthService } from '../ebay-auth.service.js'
import { ebayAccountService } from '../ebay-account.service.js'
import { EbayCategoryService } from '../ebay-category.service.js'
import { logger } from '../../utils/logger.js'
import {
  acquireEbayPublishToken,
  checkEbayCircuit,
  getEbayApiBaseForMode,
  getEbayPublishMode,
  recordEbayOutcome,
} from '../ebay-publish-gate.service.js'
import {
  digestPayload,
  writeAttemptLog,
